mapper.update:
UPDATE tbl_menu_review SET star_score = #{starScore}, review_text = #{reviewText}, updatedate = SYSDATE
WHERE review_id = #{reviewId} AND menu_id = #{menuId} AND userid = #{userid}
  AND TRUNC(regdate) = TRUNC(SYSDATE) AND is_deleted = 0

UPDATE tbl_menu SET avg_rating = (
    SELECT NVL(ROUND(AVG(star_score), 2), 0) FROM tbl_menu_review WHERE menu_id = #{menuId} AND is_deleted = 0
) WHERE menu_id = #{menuId}
